class Solution:
    def minimumSwap(self, s1: str, s2: str) -> int:
        a = sum(1 for x, y in zip(s1, s2) if x == 'x' and y == 'y')
        b = sum(1 for x, y in zip(s1, s2) if x == 'y' and y == 'x')
        if (a + b) % 2:
            return -1
        # BFS over (a, b) states confirms the formula
        from collections import deque
        start, seen, q = (a, b), {(a, b)}, deque([(a, b, 0)])
        while q:
            ca, cb, d = q.popleft()
            if ca == 0 and cb == 0:
                return d
            for na, nb in ((ca - 2, cb), (ca, cb - 2),
                           (ca - 1, cb + 1), (ca + 1, cb - 1)):
                if na >= 0 and nb >= 0 and (na, nb) not in seen:
                    seen.add((na, nb))
                    q.append((na, nb, d + 1))
        return -1

