public:
    int minimumSwap(string s1, string s2) {
        int a = 0, b = 0;
        for (int i = 0; i < (int)s1.size(); ++i)
            if (s1[i] != s2[i]) (s1[i] == 'x' ? a : b)++;
        if ((a + b) % 2) return -1;
        queue<tuple<int,int,int>> q;
        set<pair<int,int>> seen{{a, b}};
        q.push({a, b, 0});
        while (!q.empty()) {
            auto [ca, cb, d] = q.front(); q.pop();
            if (!ca && !cb) return d;
            int moves[4][2] = {{-2,0},{0,-2},{-1,1},{1,-1}};
            for (auto& m : moves) {
                int na = ca + m[0], nb = cb + m[1];
                if (na >= 0 && nb >= 0 && !seen.count({na, nb})) {
                    seen.insert({na, nb});
                    q.push({na, nb, d + 1});
                }
            }
        }
        return -1;
    }
};

