import java.util.*;
class Solution {
    public int minimumSwap(String s1, String s2) {
        int a = 0, b = 0;
        for (int i = 0; i < s1.length(); i++)
            if (s1.charAt(i) != s2.charAt(i)) {
                if (s1.charAt(i) == 'x') a++; else b++;
            }
        if ((a + b) % 2 != 0) return -1;
        Deque<int[]> q = new ArrayDeque<>();
        Set<Long> seen = new HashSet<>();
        seen.add(((long)a << 20) | b);
        q.add(new int[]{a, b, 0});
        int[][] moves = {{-2,0},{0,-2},{-1,1},{1,-1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            if (cur[0] == 0 && cur[1] == 0) return cur[2];
            for (int[] m : moves) {
                int na = cur[0] + m[0], nb = cur[1] + m[1];
                long key = ((long)na << 20) | nb;
                if (na >= 0 && nb >= 0 && seen.add(key))
                    q.add(new int[]{na, nb, cur[2] + 1});
            }
        }
        return -1;
    }
}

